NATIVELY: ```go
package lru

type node struct {
	key, val   int
	prev, next *node
}

type LRUCache struct {
	capacity   int
	items      map[int]*node
	head, tail *node // head = most recent, tail = least recent
}

func Constructor(capacity int) LRUCache {
	head := &node{}
	tail := &node{}
	head.next = tail
	tail.prev = head
	return LRUCache{
		capacity: capacity,
		items:    make(map[int]*node, capacity),
		head:     head,
		tail:     tail,
	}
}

func (c *LRUCache) Get(key int) int {
	n, ok := c.items[key]
	if !ok {
		return -1
	}
	c.moveToFront(n)
	return n.val
}

func (c *LRUCache) Put(key int, value int) {
	if n, ok := c.items[key]; ok {
		n.val = value
		c.moveToFront(n)
		return
	}
	n := &node{key: key, val: value}
	c.items[key] = n
	c.addToFront(n)
	if len(c.items) > c.capacity {
		lru := c.tail.prev
		c.remove(lru)
		delete(c.items, lru.key)
	}
}

func (c *LRUCache) addToFront(n *node) {
	n.prev = c.head
	n.next = c.head.next
	c.head.next.prev = n
	c.head.next = n
}

func (c *LRUCache) remove(n *node) {
	n.prev.next = n.next
	n.next.prev = n.prev
}

func (c *LRUCache) moveToFront(n *node) {
	c.remove(n)
	c.addToFront(n)
}
```

I hand-rolled a doubly linked list with sentinel head and tail nodes, so every insert and removal is just pointer swaps, and the map gives O(1) lookup by key. Get moves the node to the front, Put updates in place or inserts and evicts the tail when over capacity.

Time: O(1) for both Get and Put. Space: O(capacity).

